# that already exist, then seed the classification windows that express rule R10.
#
# Validated by hand, because pytest.ini sets --nomigrations and the suite builds its
# schema from the models -- a broken migration would not fail a single test.
#
# THE BACK-FILL IS DELIBERATELY TOLERANT. It matches hour types by name, and a name
# that does not match is left at the model default (1000) instead of raising. An
# installation where an admin renamed "Fora do expediente" must still be able to
# migrate: a wrong priority is a value to fix in the panel, while a migration that
# refuses to apply is an outage. Same reasoning for the window seeding below.

import django.core.validators
import django.db.models.deletion
import plane.db.mixins
import uuid
from django.conf import settings
