from plane.utils.service_catalog_seed import HOUR_TYPE_SEED, seed_classification_windows


def backfill_priorities_and_seed_windows(apps, schema_editor):
    """Give existing hour types their priority, then seed the windows of every workspace."""
    ServiceHourType = apps.get_model("db", "ServiceHourType")
    ServiceClassificationWindow = apps.get_model("db", "ServiceClassificationWindow")
    Workspace = apps.get_model("db", "Workspace")

    priority_by_name = {row["name"]: row["priority"] for row in HOUR_TYPE_SEED}

    for name, priority in priority_by_name.items():
        # Only the seeded names are touched. Anything else -- renamed, or created by an
        # admin -- keeps the model default and is inert until it is given a window,
        # because an hour type with no window is never suggested.
        ServiceHourType.objects.filter(name=name).update(priority=priority)

    workspace_ids = list(Workspace.objects.filter(deleted_at__isnull=True).values_list("id", flat=True))

    for workspace_id in workspace_ids:
        seed_classification_windows(ServiceClassificationWindow, ServiceHourType, workspace_id)


def clear_windows(apps, schema_editor):
    """Reverse of the data step.

    Only the windows are removed; `priority` disappears with its column, so there is
    nothing to undo there. Reversal is lossy for windows an admin added by hand, which
    is unavoidable -- there is no way to tell them from the seeded ones, and leaving
    them behind would orphan rows pointing at a table that is about to be dropped.
    """
    ServiceClassificationWindow = apps.get_model("db", "ServiceClassificationWindow")
    ServiceClassificationWindow.objects.all().delete()


